-- Additive physical repair and business decision schema.
PRAGMA foreign_keys = ON;
CREATE TABLE repair_stores (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,location TEXT NOT NULL,contact_id TEXT NOT NULL,availability TEXT,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_stores_lifecycle ON repair_stores(lifecycle,id);
CREATE TABLE repair_assets (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES repair_stores(id) ON DELETE RESTRICT,serial TEXT UNIQUE,trade TEXT NOT NULL,warranty_source_id TEXT,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_assets_lifecycle ON repair_assets(lifecycle,id);
CREATE INDEX repair_assets_store_id ON repair_assets(store_id,id);
CREATE TABLE repair_contractors (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,payee_id TEXT NOT NULL,email TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_contractors_lifecycle ON repair_contractors(lifecycle,id);
CREATE TABLE repair_credentials (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,contractor_id TEXT NOT NULL REFERENCES repair_contractors(id) ON DELETE RESTRICT,kind TEXT NOT NULL,trade TEXT NOT NULL,location TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_credentials_lifecycle ON repair_credentials(lifecycle,id);
CREATE INDEX repair_credentials_contractor_id ON repair_credentials(contractor_id,id);
CREATE TABLE repair_store_staff (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,store_id TEXT NOT NULL REFERENCES repair_stores(id) ON DELETE RESTRICT,principal_id TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_store_staff_lifecycle ON repair_store_staff(lifecycle,id);
CREATE INDEX repair_store_staff_store_id ON repair_store_staff(store_id,id);
CREATE TABLE repair_intakes (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,text TEXT NOT NULL,fingerprint TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,submitter_id TEXT NOT NULL,store_id TEXT REFERENCES repair_stores(id) ON DELETE RESTRICT,asset_id TEXT REFERENCES repair_assets(id) ON DELETE RESTRICT,source_ids TEXT NOT NULL,file_ids TEXT NOT NULL,candidates TEXT NOT NULL,question TEXT,case_id TEXT,work_order_id TEXT);
CREATE INDEX repair_intakes_lifecycle ON repair_intakes(lifecycle,id);
CREATE INDEX repair_intakes_store_id ON repair_intakes(store_id,id);
CREATE INDEX repair_intakes_asset_id ON repair_intakes(asset_id,id);
CREATE TABLE repair_jobs (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,intake_id TEXT NOT NULL REFERENCES repair_intakes(id) ON DELETE RESTRICT,objective TEXT NOT NULL,kind TEXT NOT NULL,case_id TEXT);
CREATE INDEX repair_jobs_lifecycle ON repair_jobs(lifecycle,id);
CREATE INDEX repair_jobs_intake_id ON repair_jobs(intake_id,id);
CREATE TABLE repair_work_orders (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,job_id TEXT NOT NULL REFERENCES repair_jobs(id) ON DELETE RESTRICT,intake_id TEXT NOT NULL UNIQUE REFERENCES repair_intakes(id) ON DELETE RESTRICT,asset_id TEXT NOT NULL REFERENCES repair_assets(id) ON DELETE RESTRICT,store_id TEXT NOT NULL REFERENCES repair_stores(id) ON DELETE RESTRICT,requester_id TEXT NOT NULL,contractor_id TEXT REFERENCES repair_contractors(id) ON DELETE RESTRICT,scope_hash TEXT NOT NULL,quote_id TEXT,completion_claim_id TEXT,acceptance_id TEXT,case_id TEXT);
CREATE INDEX repair_work_orders_lifecycle ON repair_work_orders(lifecycle,id);
CREATE INDEX repair_work_orders_job_id ON repair_work_orders(job_id,id);
CREATE INDEX repair_work_orders_intake_id ON repair_work_orders(intake_id,id);
CREATE INDEX repair_work_orders_asset_id ON repair_work_orders(asset_id,id);
CREATE INDEX repair_work_orders_store_id ON repair_work_orders(store_id,id);
CREATE INDEX repair_work_orders_contractor_id ON repair_work_orders(contractor_id,id);
CREATE TABLE repair_quotes (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,work_order_version TEXT NOT NULL,contractor_id TEXT NOT NULL REFERENCES repair_contractors(id) ON DELETE RESTRICT,contractor_version TEXT NOT NULL,payee_id TEXT NOT NULL,scope_hash TEXT NOT NULL,minor TEXT NOT NULL,currency TEXT NOT NULL,scale TEXT NOT NULL,tax_included INTEGER NOT NULL CHECK(tax_included IN (0,1)),line_items TEXT NOT NULL,exclusions TEXT NOT NULL,expires_at TEXT NOT NULL,evidence TEXT NOT NULL,offered_slot TEXT,approval_id TEXT,exact_hash TEXT NOT NULL);
CREATE INDEX repair_quotes_lifecycle ON repair_quotes(lifecycle,id);
CREATE INDEX repair_quotes_work_order_id ON repair_quotes(work_order_id,id);
CREATE INDEX repair_quotes_contractor_id ON repair_quotes(contractor_id,id);
CREATE TABLE repair_visits (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,quote_id TEXT NOT NULL REFERENCES repair_quotes(id) ON DELETE RESTRICT,start_at TEXT NOT NULL,end_at TEXT NOT NULL,attempt_id TEXT NOT NULL,receipt_id TEXT,external_id TEXT,contractor_accepted INTEGER NOT NULL CHECK(contractor_accepted IN (0,1)));
CREATE INDEX repair_visits_lifecycle ON repair_visits(lifecycle,id);
CREATE INDEX repair_visits_work_order_id ON repair_visits(work_order_id,id);
CREATE INDEX repair_visits_quote_id ON repair_visits(quote_id,id);
CREATE TABLE repair_completion_claims (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,visit_id TEXT NOT NULL REFERENCES repair_visits(id) ON DELETE RESTRICT,scope_hash TEXT NOT NULL,source_ids TEXT NOT NULL,evidence TEXT NOT NULL,author_id TEXT NOT NULL);
CREATE INDEX repair_completion_claims_lifecycle ON repair_completion_claims(lifecycle,id);
CREATE INDEX repair_completion_claims_work_order_id ON repair_completion_claims(work_order_id,id);
CREATE INDEX repair_completion_claims_visit_id ON repair_completion_claims(visit_id,id);
CREATE TABLE repair_acceptances (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,claim_id TEXT NOT NULL REFERENCES repair_completion_claims(id) ON DELETE RESTRICT,claim_version TEXT NOT NULL,actor_id TEXT NOT NULL,accepted INTEGER NOT NULL CHECK(accepted IN (0,1)),reason TEXT NOT NULL,evidence TEXT NOT NULL,scope_hash TEXT NOT NULL);
CREATE INDEX repair_acceptances_lifecycle ON repair_acceptances(lifecycle,id);
CREATE INDEX repair_acceptances_work_order_id ON repair_acceptances(work_order_id,id);
CREATE INDEX repair_acceptances_claim_id ON repair_acceptances(claim_id,id);
CREATE TABLE repair_invoices (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,source_id TEXT NOT NULL UNIQUE,source_version TEXT NOT NULL,invoice_number TEXT NOT NULL,payee_id TEXT NOT NULL,minor TEXT NOT NULL,currency TEXT NOT NULL,scale TEXT NOT NULL,scope_hash TEXT NOT NULL,evidence TEXT NOT NULL);
CREATE INDEX repair_invoices_lifecycle ON repair_invoices(lifecycle,id);
CREATE INDEX repair_invoices_work_order_id ON repair_invoices(work_order_id,id);
CREATE TABLE repair_handoffs (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,invoice_id TEXT NOT NULL UNIQUE REFERENCES repair_invoices(id) ON DELETE RESTRICT,quote_id TEXT NOT NULL REFERENCES repair_quotes(id) ON DELETE RESTRICT,acceptance_id TEXT NOT NULL REFERENCES repair_acceptances(id) ON DELETE RESTRICT,attempt_id TEXT NOT NULL,receipt_id TEXT,external_id TEXT,readback_verified INTEGER NOT NULL CHECK(readback_verified IN (0,1)));
CREATE INDEX repair_handoffs_lifecycle ON repair_handoffs(lifecycle,id);
CREATE INDEX repair_handoffs_work_order_id ON repair_handoffs(work_order_id,id);
CREATE INDEX repair_handoffs_invoice_id ON repair_handoffs(invoice_id,id);
CREATE INDEX repair_handoffs_quote_id ON repair_handoffs(quote_id,id);
CREATE INDEX repair_handoffs_acceptance_id ON repair_handoffs(acceptance_id,id);
CREATE TABLE business_decisions (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,kind TEXT NOT NULL,requester_id TEXT NOT NULL,requester_kind TEXT NOT NULL,assignee_id TEXT,subject_json TEXT NOT NULL,exact_input_hash TEXT NOT NULL,recommendation TEXT NOT NULL,alternatives TEXT NOT NULL,impact TEXT NOT NULL,evidence TEXT NOT NULL,freshness TEXT NOT NULL,due_at TEXT NOT NULL,expires_at TEXT,rationale TEXT,decided_by TEXT,decided_at TEXT,supersedes_id TEXT,proposal_id TEXT);
CREATE INDEX business_decisions_lifecycle ON business_decisions(lifecycle,id);
CREATE UNIQUE INDEX repair_invoice_identity ON repair_invoices(payee_id,invoice_number);
CREATE UNIQUE INDEX repair_staff_identity ON repair_store_staff(store_id,principal_id);
CREATE TABLE repair_configuration(app_id TEXT PRIMARY KEY,manager_id TEXT NOT NULL,release_id TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
